using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace WorkerService
{
    public sealed class RateLimitState
    {
        private long _tokenCount;
        private long _lastRefillTicks;
        private readonly long _maxTokens;
        private readonly long _refillIntervalTicks;
        private readonly object _lock = new object();

        public RateLimitState(long maxTokens, TimeSpan refillInterval)
        {
            _maxTokens = maxTokens;
            _refillIntervalTicks = refillInterval.Ticks;
            _tokenCount = maxTokens;
            _lastRefillTicks = DateTime.UtcNow.Ticks;
        }

        public bool TryConsume(int count = 1)
        {
            lock (_lock)
            {
                RefillTokens();
                if (_tokenCount >= count)
                {
                    _tokenCount -= count;
                    return true;
                }
                return false;
            }
        }

        private void RefillTokens()
        {
            long now = DateTime.UtcNow.Ticks;
            long elapsed = now - _lastRefillTicks;
            if (elapsed >= _refillIntervalTicks)
            {
                long periods = elapsed / _refillIntervalTicks;
                _tokenCount = Math.Min(_maxTokens, _tokenCount + periods * _maxTokens);
                _lastRefillTicks = _lastRefillTicks + periods * _refillIntervalTicks;
            }
        }

        public long CurrentTokens => Interlocked.Read(ref _tokenCount);
    }

    public interface IAuditLogger
    {
        Task LogAsync(string tenantId, string action, string detail);
    }

    public class AuditLogger : IAuditLogger
    {
        private readonly ILogger<AuditLogger> _logger;

        public AuditLogger(ILogger<AuditLogger> logger)
        {
            _logger = logger;
        }

        public Task LogAsync(string tenantId, string action, string detail)
        {
            _logger.LogInformation("[Audit] Tenant={TenantId} Action={Action} Detail={Detail}",
                tenantId, action, detail);
            return Task.CompletedTask;
        }
    }

    public class JobRequest
    {
        public string TenantId { get; set; }
        public string JobType { get; set; }
        public byte[] Payload { get; set; }
        public DateTime SubmittedAt { get; set; }
    }

    public class JobWorker
    {
        private readonly ConcurrentDictionary<string, RateLimitState> _rateLimiters;
        private readonly IAuditLogger _auditLogger;
        private readonly ILogger<JobWorker> _logger;
        private const int MaxJobsPerMinute = 10;
        private static readonly TimeSpan RefillInterval = TimeSpan.FromMinutes(1);

        public JobWorker(IAuditLogger auditLogger, ILogger<JobWorker> logger)
        {
            _rateLimiters = new ConcurrentDictionary<string, RateLimitState>();
            _auditLogger = auditLogger;
            _logger = logger;
        }

        public async Task<JobResult> ProcessJobAsync(JobRequest request, CancellationToken ct)
        {
            if (request == null) throw new ArgumentNullException(nameof(request));
            if (string.IsNullOrWhiteSpace(request.TenantId))
                throw new ArgumentException("TenantId is required");

            var normalizedTenant = NormalizeTenantId(request.TenantId);
            var limiter = _rateLimiters.GetOrAdd(normalizedTenant,
                _ => new RateLimitState(MaxJobsPerMinute, RefillInterval));

            if (!limiter.TryConsume())
            {
                await _auditLogger.LogAsync(normalizedTenant, "RATE_LIMITED",
                    $"Job {request.JobType} rejected. Tokens remaining: {limiter.CurrentTokens}");
                return new JobResult { Success = false, Error = "Rate limit exceeded" };
            }

            await _auditLogger.LogAsync(normalizedTenant, "JOB_ACCEPTED",
                $"Processing {request.JobType}");

            try
            {
                var result = await ExecuteJobAsync(request, ct);
                await _auditLogger.LogAsync(normalizedTenant, "JOB_COMPLETED",
                    $"Job {request.JobType} completed successfully");
                return result;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Job failed for tenant {TenantId}", normalizedTenant);
                await _auditLogger.LogAsync(normalizedTenant, "JOB_FAILED",
                    $"Job {request.JobType} failed: {ex.Message}");
                return new JobResult { Success = false, Error = "Internal error" };
            }
        }

        private string NormalizeTenantId(string tenantId)
        {
            // Normalize using Unicode NFKC form for consistent key lookup
            var normalized = tenantId.Trim().Normalize(System.Text.NormalizationForm.FormKC);
            return normalized.ToUpperInvariant();
        }

        private async Task<JobResult> ExecuteJobAsync(JobRequest request, CancellationToken ct)
        {
            await Task.Delay(100, ct); // Simulate work
            return new JobResult { Success = true, Data = $"Processed {request.JobType}" };
        }
    }

    public class BatchJobSubmitter
    {
        private readonly JobWorker _worker;
        private readonly IAuditLogger _auditLogger;

        public BatchJobSubmitter(JobWorker worker, IAuditLogger auditLogger)
        {
            _worker = worker;
            _auditLogger = auditLogger;
        }

        public async Task<BatchResult> SubmitBatchAsync(JobRequest[] jobs, CancellationToken ct)
        {
            if (jobs == null || jobs.Length == 0)
                return new BatchResult { Processed = 0, Failed = 0 };

            // Deduplicate by tenant to apply batch-level rate check
            var tenantGroups = new ConcurrentDictionary<string, int>();
            foreach (var job in jobs)
            {
                var key = job.TenantId?.Trim().Normalize(System.Text.NormalizationForm.FormKC)
                    .ToUpperInvariant() ?? "UNKNOWN";
                tenantGroups.AddOrUpdate(key, 1, (_, count) => count + 1);
            }

            await _auditLogger.LogAsync("SYSTEM", "BATCH_SUBMIT",
                $"Batch of {jobs.Length} jobs from {tenantGroups.Count} tenants");

            int processed = 0, failed = 0;
            foreach (var job in jobs)
            {
                ct.ThrowIfCancellationRequested();
                var result = await _worker.ProcessJobAsync(job, ct);
                if (result.Success) processed++;
                else failed++;
            }

            return new BatchResult { Processed = processed, Failed = failed };
        }
    }

    public class JobResult
    {
        public bool Success { get; set; }
        public string Error { get; set; }
        public string Data { get; set; }
    }

    public class BatchResult
    {
        public int Processed { get; set; }
        public int Failed { get; set; }
    }
}
